async function hashFile(file) {
  const digest = crypto.createHash('sha256');
  for await (const chunk of fs.createReadStream(file)) digest.update(chunk);
  return digest.digest('hex');
}

async function snapshotTree(root) {
  const entries = [];
  async function visit(directory, prefix) {
    const children = await fsp.readdir(directory, { withFileTypes: true });
    children.sort((a, b) => a.name.localeCompare(b.name));
    for (const item of children) {
      assert.equal(item.isSymbolicLink(), false, 'Synthetic fixture must not use links');
      const full = path.join(directory, item.name);
      const relative = prefix ? prefix + '/' + item.name : item.name;
      if (item.isDirectory()) await visit(full, relative);
      else if (item.isFile()) entries.push([relative, (await fsp.stat(full)).size, await hashFile(full)]);
    }
  }
  await visit(root, '');
  return crypto.createHash('sha256').update(JSON.stringify(entries)).digest('hex');
}

async function runFixture(runtime, fixturePath, action, values = {}) {
  const output = await run(runtime.p.php, [...runtime.phpArgs(), fixturePath], {
    env: { ...runtime.env, DL_MIGRATION_BUNDLE: runtime.p.bundle },
    cwd: runtime.p.backend,
    input: JSON.stringify({ action, ...values }),
    timeout: 180000,
  });
  const result = JSON.parse(output);
  assert.equal(result.ok, true, 'Synthetic PHP fixture did not complete');
  return result;
}

async function phpPreflightDiagnostic(bundle, dataPath, vault, label, extensionDirOverride, relativeIni = false) {
  // Deliberately inspect only PHP/extension metadata. Never call phpinfo(),
  // print environment variables, boot Laravel, or open a database here.
  await fsp.mkdir(path.join(dataPath, 'tmp'), { recursive: true });
  const diagnosticRuntime = new Runtime(paths(bundle, dataPath), vault);
  const environment = Object.fromEntries(Object.entries(process.env).filter(([name]) =>
    /^(SYSTEMROOT|WINDIR|COMSPEC|TEMP|TMP|PATH|PATHEXT|USERPROFILE|LOCALAPPDATA|APPDATA|PROCESSOR_ARCHITECTURE)$/i.test(name)));
  const commonArgs = [...diagnosticRuntime.phpArgs(),
    '-d', 'display_startup_errors=1', '-d', 'display_errors=stderr',
    '-d', 'error_reporting=-1', '-d', 'log_errors=0'];
  if (relativeIni) commonArgs[1] = '../php/php.ini';
  // Diagnostic only: cwd is bundle/backend, so this ASCII relative value
  // isolates extension loading from an absolute Windows Unicode path.
  if (extensionDirOverride) commonArgs.push('-d', 'extension_dir=' + extensionDirOverride);
  async function capture(args) {
    const child = spawn(diagnosticRuntime.p.php, args, {
      cwd: diagnosticRuntime.p.backend, env: environment,
      shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '', stderr = '', timer;
    child.stdout.on('data', chunk => { if (stdout.length < 32768) stdout += chunk.toString('utf8'); });
    child.stderr.on('data', chunk => { if (stderr.length < 32768) stderr += chunk.toString('utf8'); });
    const result = await new Promise(resolve => {
      child.once('error', error => {
        clearTimeout(timer);
        resolve({ exitCode: null, stdout, stderr, spawnError: error.code || 'SPAWN_FAILED' });
      });
      child.once('close', exitCode => { clearTimeout(timer); resolve({ exitCode, stdout, stderr }); });
      timer = setTimeout(() => { child.kill(); resolve({ exitCode: null, stdout, stderr, timedOut: true }); }, 30000);
    });
    clearTimeout(timer);
    return result;
  }
  const phpCode = [
    '$ext = ini_get("extension_dir");',
    '$meta = [',
    '"phpVersion" => PHP_VERSION,',
    '"phpBinary" => PHP_BINARY,',
    '"loadedIni" => php_ini_loaded_file(),',
    '"scannedIniFiles" => php_ini_scanned_files(),',
    '"extensionDir" => $ext,',
    '"extensionDirExists" => is_dir($ext),',
    '"pdoMysqlDllExists" => is_file($ext . "/php_pdo_mysql.dll"),',
    '"pdoMysqlAlternativeDllExists" => is_file($ext . "/pdo_mysql.dll"),',
    '"pdoLoaded" => extension_loaded("PDO"),',
    '"pdoMysqlLoaded" => extension_loaded("pdo_mysql"),',
    '"availableDrivers" => class_exists("PDO") ? PDO::getAvailableDrivers() : [],',
    '];',
    'echo json_encode($meta, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);',
  ].join(' ');
  const modules = await capture([...commonArgs, '-m']);
  const metadata = await capture([...commonArgs, '-r', phpCode]);
  let parsedMetadata;
  try { parsedMetadata = JSON.parse(metadata.stdout); } catch { parsedMetadata = null; }
  const result = {
    label, bundle, phpArgs: commonArgs,
    nodeMysqlDllExists: fs.existsSync(path.join(bundle, 'php', 'ext', 'php_pdo_mysql.dll')),
    modules, metadata, parsedMetadata,
  };
  console.log('PHP preflight ' + label + ': ' + JSON.stringify(parsedMetadata || { metadataExitCode: metadata.exitCode }));
  return result;
}

async function dumpDatabase(runtime, destination) {
  const filename = path.join(runtime.p.maria, 'mariadb-dump.exe');
  assert.ok(fs.existsSync(filename), 'Bundled mariadb-dump.exe is required for this test');
  const child = spawn(filename, [
    '--no-defaults', '--protocol=tcp', '--host=127.0.0.1', '--port=' + runtime.dbPort,
    '--user=root', '--default-character-set=utf8mb4', '--single-transaction',
    '--skip-lock-tables', '--skip-add-locks', '--skip-comments', '--hex-blob',
    'digital_lab_desktop',
  ], {
    env: { ...process.env, MYSQL_PWD: runtime.secrets.rootPassword },
    cwd: runtime.p.maria, windowsHide: true, shell: false, stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stderr = '';
  child.stderr.on('data', data => { if (stderr.length < 8000) stderr += data.toString(); });
  let timer;
  const closed = new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('close', code => {
      clearTimeout(timer);
      code === 0 ? resolve() : reject(new Error('Synthetic dump failed: ' + stderr));
    });
    timer = setTimeout(() => { child.kill(); reject(new Error('Synthetic dump timed out')); }, 180000);
  });
  closed.catch(() => {});
  const digest = crypto.createHash('sha256');
  let bytes = 0;
  const meter = new Transform({
    transform(chunk, _encoding, done) { digest.update(chunk); bytes += chunk.length; done(null, chunk); },
  });
  try {
    await Promise.all([
      closed,
      pipeline(child.stdout, meter, zlib.createBrotliCompress({
        params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 4 },
      }), fs.createWriteStream(destination, { flags: 'wx' })),
    ]);
    return { sha256: digest.digest('hex'), uncompressedBytes: bytes };
  } finally { clearTimeout(timer); }
}

async function runConverter(executable, config, label) {
  const child = spawn(executable, [path.join(toolRoot, 'src', 'migrate.cjs'), '--config-stdin'], {
    env: { ...process.env, ELECTRON_RUN_AS_NODE: '1' },
    cwd: toolRoot, windowsHide: true, shell: false, stdio: ['pipe', 'pipe', 'pipe'],
  });
  const events = [];
  const phases = new Set();
  let result, stderr = '';
  child.stderr.on('data', data => { if (stderr.length < 8000) stderr += data.toString(); });
  const lines = readline.createInterface({ input: child.stdout });
  lines.on('line', line => {
    if (!line.trim()) return;
    try {
      const event = JSON.parse(line);
      events.push(event);
      if (event.type === 'progress' && !phases.has(event.phase)) {
        phases.add(event.phase);
        console.log('  ' + label + ': ' + event.phase);
      }
      if (event.type === 'result') result = event;
    } catch { /* Electron startup noise is not part of the protocol. */ }
  });
  let timer;
  const close = new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('close', code => { clearTimeout(timer); resolve(code); });
    timer = setTimeout(() => {
      // These are disposable synthetic CI processes, never an installed user's
      // live application. Terminate only this exact test process tree on timeout.
      spawnSync('taskkill.exe', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true });
      reject(new Error('Synthetic converter run timed out: ' + label));
    }, 10 * 60 * 1000);
  });
  child.stdin.on('error', () => {});
  child.stdin.end(Buffer.from(JSON.stringify(config), 'utf8'));
  const exitCode = await close;
  lines.close();
  assert.ok(result, 'Converter did not emit a result for ' + label + ': ' + stderr);
  return { result, exitCode, phases, events };
}

async function smokeUi(fixtureDirectory, outputDirectory, installationDir) {
  const powershell = path.join(process.env.SYSTEMROOT, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe');
  const wizard = path.join(toolRoot, 'Transfer-Wizard.ps1');
  await run(powershell, [
    '-NoLogo', '-NoProfile', '-NonInteractive', '-STA', '-ExecutionPolicy', 'Bypass',
    '-File', wizard, '-UiSmokeTest', '-SmokeFixtureRoot', fixtureDirectory,
    '-SmokeOutputPath', path.join(outputDirectory, 'migration-ui.png'),
  ], {
    env: { ...process.env, DLM_SYNTHETIC_TEST: '1', DLM_TEST_INSTALLATION: installationDir },
    cwd: toolRoot, timeout: 60000,
  });
  const screenshot = path.join(outputDirectory, 'migration-ui.png');
  assert.ok((await fsp.stat(screenshot)).size > 1000, 'WinForms screenshot was not produced');
}

